/**
 * tseZharfaKavosh — browser bundle parity test v0.1.0 (node)
 *
 * src/engine/tseEngine.browser.v1.js is GENERATED by tools/buildBrowserBundle.v1.js
 * (comment/blank-line stripping + module wrapper). This test proves that stripping
 * changed nothing that matters: the BUNDLED engine must produce verdict-for-verdict
 * the same results as the ORIGINAL modules, on every row of a wide fixture set.
 *
 * What is compared:
 *   1. VERSION / DEFAULT_FUNNEL_CONFIG / DIRTY_FIELDS identity
 *   2. bsGreeks / impliedVol / normCDF on a spread of inputs
 *   3. calendar.daysToExpiry on real Jalali labels
 *   4. optionParser.parseOptionLabel on real l18/l30 shapes
 *   5. computeFunnel on every fixture row (deep JSON equality, inputs included)
 *   6. a full run() + publish() cycle: identical bitset / known / index bytes
 *
 * Run: node probes/bundle.parity.v1.js
 * SPDX-License-Identifier: Smart-FFA-1.1
 */
'use strict';

const path = require('path');
const fs = require('fs');
const ROOT = path.join(__dirname, '..');
const BUNDLE = path.join(ROOT, 'src/engine/tseEngine.browser.v1.js');

if (!fs.existsSync(BUNDLE)) {
  console.error('FAIL  bundle missing: ' + BUNDLE + '  (run: node tools/buildBrowserBundle.v1.js)');
  process.exit(1);
}

// ---------- the originals ----------
const OP = require(path.join(ROOT, 'src/optionParser.v0.1.0.js'));
const G = require(path.join(ROOT, 'src/models/greeks.v0.1.0.js'));
const CAL = require(path.join(ROOT, 'src/models/jalaliCalendar.v0.1.0.js'));
const ENG = require(path.join(ROOT, 'src/engine/bEngine.v0.1.0.js'));

// ---------- the bundle ----------
// The bundle is an IIFE that writes to globalThis (no window in node).
delete globalThis.TseBEngine; delete globalThis.TseModels;
require(BUNDLE);
const BENG = globalThis.TseBEngine;
const BM = globalThis.TseModels;
if (!BENG || !BM) {
  console.error('FAIL  bundle did not define globalThis.TseBEngine / TseModels');
  process.exit(1);
}

let pass = 0, fail = 0;
const failures = [];
function check(name, cond, extra) {
  if (cond) { pass++; console.log('  PASS  ' + name + (extra ? '  (' + extra + ')' : '')); }
  else { fail++; failures.push(name); console.log('  FAIL  ' + name + (extra ? '  (' + extra + ')' : '')); }
}
function section(t) { console.log('\n=== ' + t + ' ==='); }
function eq(a, b) { return JSON.stringify(a) === JSON.stringify(b); }

// ---------- a wide fixture set ----------
const UNDERLYINGS = ['اهرم', 'بساما', 'فولاد', 'شپنا', 'وبانک', 'خودرو', 'کچاد', 'پارس', 'مبین', 'آرمان'];
const SPOT_OF = { 'اهرم': 72813, 'بساما': 44000, 'فولاد': 27500, 'شپنا': 61500, 'وبانک': 22000,
  'خودرو': 15000, 'کچاد': 79500, 'پارس': 53000, 'مبین': 36000, 'آرمان': 49000 };
const FIXED_NOW_MS = new Date(2026, 9, 18, 12, 0, 0).getTime();
const TOTAL = 900;

function expiryFor(dte) {
  const j = CAL.jdnToJalali(CAL.localDateToJDN(new Date(FIXED_NOW_MS)) + dte);
  return j.jy + '/' + String(j.jm).padStart(2, '0') + '/' + String(j.jd).padStart(2, '0');
}

function makeRows(n) {
  const rows = [];
  for (let i = 0; i < n; i++) {
    const kind = (i % 2 === 0) ? 'call' : 'put';
    const u = UNDERLYINGS[i % UNDERLYINGS.length];
    const S = SPOT_OF[u];
    const inscode = String(400000000000000 + i * 7919);
    const base = { inscode, tvol: 1000 + (i % 9000), tno: (i % 11 === 0 ? 0 : 20 + (i % 300)) };
    const mode = i % 9;
    if (mode === 3) {
      // an option with no parsable label -> insufficient-data (fail-open)
      base.l18 = 'something'; base.l30 = 'not an option label';
      base.pl = S; base.pc = S;
    } else if (mode === 4) {
      // a stock row
      base.l18 = u; base.l30 = u; base.pl = S; base.pc = S;
    } else if (mode === 5) {
      // an option with no expiry -> insufficient-data
      base.l18 = (kind === 'call' ? 'ض' : 'ط') + u + 3000;
      base.l30 = (kind === 'call' ? 'اختیارخ ' : 'اختیارف ') + u;
      base.pl = 120; base.pc = 118;
    } else if (mode === 6) {
      // an option with an empty book and no trade -> market price unresolved
      base.l18 = (kind === 'call' ? 'ض' : 'ط') + u + 3000;
      base.l30 = (kind === 'call' ? 'اختیارخ ' : 'اختیارف ') + u + '-3000-' + expiryFor(30);
      base.pl = 0; base.pc = 0; base.pd1 = 0; base.po1 = 0;
    } else if (mode === 7) {
      // a deliberately RICH option: IV should land above ivMax -> pass=false
      const strike = Math.round((S * 1.02) / 500) * 500;
      const dte = 14, T = dte / 365, r = 0.30, sigma = 0.35;
      base.l18 = (kind === 'call' ? 'ض' : 'ط') + u + strike;
      base.l30 = (kind === 'call' ? 'اختیارخ ' : 'اختیارف ') + u + '-' + strike + '-' + expiryFor(dte);
      const g = G.bsGreeks({ S, K: strike, T, r, sigma, kind });
      const disc = Math.exp(-r * T);
      const arbHi = kind === 'put' ? strike * disc : S;
      base.pl = Math.min(arbHi, Math.max(1, g.price) * 3.0); base.pc = Math.max(1, g.price) * 2.0;
      base.pd1 = base.pl * 0.99; base.po1 = base.pl * 1.01;
    } else if (mode === 8) {
      // a deliberately CHEAP option: IV should land below ivMin -> pass=false
      const strike = Math.round((S * 0.98) / 500) * 500;
      const dte = 90, T = dte / 365, r = 0.30, sigma = 0.35;
      base.l18 = (kind === 'call' ? 'ض' : 'ط') + u + strike;
      base.l30 = (kind === 'call' ? 'اختیارخ ' : 'اختیارف ') + u + '-' + strike + '-' + expiryFor(dte);
      const g = G.bsGreeks({ S, K: strike, T, r, sigma, kind });
      const disc = Math.exp(-r * T);
      const arbLo = kind === 'put' ? Math.max(0, strike * disc - S) : Math.max(0, S - strike * disc);
      base.pl = Math.max(arbLo, Math.max(1, g.price) * 0.05); base.pc = Math.max(1, g.price) * 0.06;
      base.pd1 = base.pl * 0.99; base.po1 = base.pl * 1.01;
    } else {
      // a normal option
      const strike = Math.round((S * (0.85 + 0.3 * ((i % 17) / 16))) / 500) * 500;
      const dte = [7, 14, 30, 60, 90][i % 5];
      const T = dte / 365, r = 0.30, sigma = 0.35;
      base.l18 = (kind === 'call' ? 'ض' : 'ط') + u + strike;
      base.l30 = (kind === 'call' ? 'اختیارخ ' : 'اختیارف ') + u + '-' + strike + '-' + expiryFor(dte);
      const g = G.bsGreeks({ S, K: strike, T, r, sigma, kind });
      const disc = Math.exp(-r * T);
      const arbLo = kind === 'put' ? Math.max(0, strike * disc - S) : Math.max(0, S - strike * disc);
      const arbHi = kind === 'put' ? strike * disc : S;
      const last = Math.min(arbHi, Math.max(arbLo, Math.max(1, g.price) * (1 + ((i % 7) - 3) * 0.01)));
      base.pl = last; base.pc = Math.max(1, g.price) * 0.98;
      base.plc = last - base.pc; base.pcp = ((last - base.pc) / base.pc) * 100;
      base.plp = base.pcp; base.pd1 = last * 0.995; base.po1 = last * 1.005;
    }
    rows.push(base);
  }
  return rows;
}

const models = { parseOptionLabel: OP.parseOptionLabel, impliedVol: G.impliedVol, bsGreeks: G.bsGreeks };
const bmodels = { parseOptionLabel: BM.optionParser.parseOptionLabel, impliedVol: BM.greeks.impliedVol, bsGreeks: BM.greeks.bsGreeks };
const nowFn = function () { return FIXED_NOW_MS; };

// ---------- 1. identity of the exported surface ----------
section('1. exported surface');
check('VERSION identical', BENG.VERSION === ENG.VERSION, BENG.VERSION);
check('DIRTY_FIELDS identical', eq(BENG.DIRTY_FIELDS, ENG.DIRTY_FIELDS));
check('DEFAULT_FUNNEL_CONFIG identical', eq(BENG.DEFAULT_FUNNEL_CONFIG, ENG.DEFAULT_FUNNEL_CONFIG));
check('greeks VERSION identical', BM.greeks.VERSION === G.VERSION);
check('bundle is smaller than the raw sources', fs.statSync(BUNDLE).size < 56029,
  fs.statSync(BUNDLE).size + ' bytes');

// ---------- 2. model functions ----------
section('2. greeks + calendar + parser');
{
  let okG = true, okI = true, okC = true, okP = true, nG = 0;
  for (let i = 0; i < 400; i++) {
    const S = 1000 + (i * 137) % 90000;
    const K = Math.round(S * (0.6 + ((i * 53) % 80) / 100) / 500) * 500;
    const T = 0.01 + ((i * 29) % 120) / 365;
    const sigma = 0.02 + ((i * 17) % 60) / 100;
    const kind = (i % 2) ? 'put' : 'call';
    const r = 0.30;
    const a = G.bsGreeks({ S, K, T, r, sigma, kind });
    const b = BM.greeks.bsGreeks({ S, K, T, r, sigma, kind });
    if (!eq(a, b)) okG = false;
    const pa = G.normCDF(((i % 13) - 6) / 2);
    const pb = BM.greeks.normCDF(((i % 13) - 6) / 2);
    if (pa !== pb) okG = false;
    // impliedVol round-trip through the fair price, then a perturbed price
    const fair = a.price;
    if (fair && fair > 0.001) {
      const ia = G.impliedVol({ S, K, T, r, kind, marketPrice: fair });
      const ib = BM.greeks.impliedVol({ S, K, T, r, kind, marketPrice: fair });
      if (!eq(ia, ib)) okI = false;
      const ia2 = G.impliedVol({ S, K, T, r, kind, marketPrice: fair * 1.04 });
      const ib2 = BM.greeks.impliedVol({ S, K, T, r, kind, marketPrice: fair * 1.04 });
      if (!eq(ia2, ib2)) okI = false;
    }
    nG++;
  }
  check('bsGreeks/normCDF identical over ' + nG + ' inputs', okG);

  // calendar on real Jalali labels, including past expiries and garbage
  const labels = [expiryFor(1), expiryFor(30), expiryFor(180), '1404/12/29', '1400/01/01',
    '', 'garbage', '1405/13/45', '1405/7/9', '14050709', null, undefined, '۱۴۰۵/۰۷/۰۹'];
  let okCal = true;
  for (const lb of labels) {
    if (CAL.daysToExpiry(lb, FIXED_NOW_MS) !== BM.calendar.daysToExpiry(lb, FIXED_NOW_MS)) okCal = false;
  }
  check('calendar.daysToExpiry identical on ' + labels.length + ' labels', okCal);
  check('jdnToJalali round trip identical',
    eq(CAL.jdnToJalali(2461000), BM.calendar.jdnToJalali(2461000)));

  const rows = makeRows(TOTAL);
  for (const row of rows) {
    if (!eq(OP.parseOptionLabel(row), BM.optionParser.parseOptionLabel(row))) { okP = false; break; }
  }
  check('parseOptionLabel identical on all ' + TOTAL + ' rows', okP);
}

// ---------- 3. computeFunnel, row by row ----------
section('3. computeFunnel (row by row, deep equality)');
{
  const bOrig = ENG.createBEngine({ models: models, now: nowFn });
  const bBundle = BENG.createBEngine({ models: bmodels, now: nowFn });
  const rows = makeRows(TOTAL);
  // The index must exist first: resolveUnderlying reads state.underlyingMap,
  // which buildIndex() fills from the stock rows (underlyingFrom:'underlyingMap',
  // underlyingPriceField:'pc'). Without it every row is "missing S/K".
  bOrig.buildIndex(rows);
  bBundle.buildIndex(rows);
  let mismatches = 0, firstBad = null;
  const stats = { ok: 0, insufficient: 0, error: 0, passTrue: 0, ivStatus: {} };
  for (const row of rows) {
    const a = bOrig.computeFunnel(row, OP.parseOptionLabel(row));
    const b = bBundle.computeFunnel(row, BM.optionParser.parseOptionLabel(row));
    if (!eq(a, b)) { mismatches++; if (!firstBad) firstBad = { inscode: row.inscode, orig: a, bundle: b }; }
    stats[a.status] = (stats[a.status] || 0) + 1;
    if (a.status === 'ok' && a.pass === true) stats.passTrue++;
    if (a.ivStatus) stats.ivStatus[a.ivStatus] = (stats.ivStatus[a.ivStatus] || 0) + 1;
  }
  check('computeFunnel identical on ' + TOTAL + ' rows', mismatches === 0,
    'mismatches=' + mismatches + (firstBad ? ' first=' + firstBad.inscode : ''));
  console.log('        stats: ' + JSON.stringify(stats));
}

// ---------- 4. full cycle + published projection ----------
section('4. run() + publish() cycle');
{
  const rows = makeRows(TOTAL);
  const mw = { RoundNo: 7, AllRows: {}, FilterCode: '' };
  rows.forEach(r => { mw.AllRows[r.inscode] = r; });
  const bOrig = ENG.createBEngine({ models: models, now: nowFn });
  const bBundle = BENG.createBEngine({ models: bmodels, now: nowFn });
  const snap = 'snap-7-' + Object.keys(mw.AllRows).length;
  const cfg = '0-0';
  const r1 = bOrig.run(rows, snap, cfg);
  const r2 = bBundle.run(rows, snap, cfg);
  const p1 = {}, p2 = {};
  bOrig.publish(p1); bBundle.publish(p2);
  check('run() reports identical', eq(r1, r2), JSON.stringify(r1));
  check('published symbols identical', eq(p1.__B_symbols, p2.__B_symbols), 'n=' + p1.__B_symbols.length);
  check('published bitset identical (byte for byte)',
    Buffer.from(p1.__B_bitset).equals(Buffer.from(p2.__B_bitset)), p1.__B_bitset.length + ' bytes');
  check('published known mask identical',
    Buffer.from(p1.__B_known).equals(Buffer.from(p2.__B_known)), p1.__B_known.length + ' bytes');
  check('published index identical', eq(p1.__B_index, p2.__B_index));
  check('published snapshotId/configHash identical',
    p1.__B_snapshotId === p2.__B_snapshotId && p1.__B_configHash === p2.__B_configHash);
  const known = p1.__B_known;
  let knownCount = 0, hiddenCount = 0;
  for (let i = 0; i < known.length; i++) {
    for (let bit = 0; bit < 8; bit++) {
      const pos = i * 8 + bit;
      if (pos >= p1.__B_symbols.length) break;
      if (known[i] & (1 << bit)) {
        knownCount++;
        if (!(p1.__B_bitset[i] & (1 << bit))) hiddenCount++;
      }
    }
  }
  console.log('        projection: ' + p1.__B_symbols.length + ' symbols, ' + knownCount +
    ' computed, ' + hiddenCount + ' hidden, ' + (p1.__B_symbols.length - knownCount) + ' fail-open');
}

// ---------- 5. the A body itself ----------
section('5. A body (aLookup)');
{
  const AL = require(path.join(ROOT, 'src/engine/aLookup.v0.1.0.js'));
  const BA = globalThis.TseLookup;
  check('TseLookup exposed by the bundle', !!BA, typeof BA);
  check('aLookup VERSION identical', BA.VERSION === AL.VERSION, BA.VERSION);
  check('FILTER_CODE_LIMIT identical', BA.FILTER_CODE_LIMIT === AL.FILTER_CODE_LIMIT);

  const bodyOrig = AL.buildFilterCodeBody();
  const bodyBundle = BA.buildFilterCodeBody();
  check('buildFilterCodeBody() byte identical', bodyOrig === bodyBundle, bodyOrig.length + ' bytes');
  check('capacity check fits', BA.buildFilterCode().fits === true,
    BA.buildFilterCode().bytes + '/' + BA.buildFilterCode().limit);

  // execute BOTH bodies over a projection that mixes every verdict, and compare
  const symbols = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'];
  const bitset = new Uint8Array([0b10110010]);       // pos0..7
  const known = new Uint8Array([0b11110100]);        // pos0,1,2,5,6,7 computed
  const index = {}; symbols.forEach(function (s, i) { index[s] = i; });
  const published = { ok: true, index: index, bitset: bitset, known: known, symbols: symbols };
  const fnOrig = AL.compileFilterCodeBody(bodyOrig);
  const fnBundle = BA.compileFilterCodeBody(bodyBundle);
  let mism = 0;
  const expect = [];
  symbols.forEach(function (s, i) {
    const mwLike = { __B_index: index, __B_bitset: bitset, __B_known: known };
    const a = fnOrig({ inscode: s }, mwLike);
    const b = fnBundle({ inscode: s }, mwLike);
    if (a !== b) mism++;
    // also the pure evaluator must agree with the executed body
    const c = BA.evaluateRow({ inscode: s }, published);
    if (a !== c) mism++;
    expect.push(s + '=' + a);
  });
  check('executed body identical + agrees with evaluateRow on 8 symbols', mism === 0,
    'mismatches=' + mism + ' [' + expect.join(' ') + ']');

  // fail-open corners of the same body: empty projection, missing key, no index
  const corners = [
    ['no projection at all', {}, 'x'],
    ['empty index', { __B_index: {}, __B_bitset: bitset, __B_known: known }, 'zzz'],
    ['known shorter than index', { __B_index: { x: 999 }, __B_bitset: bitset, __B_known: new Uint8Array(1) }, 'x'],
    ['bit not computed', { __B_index: { x: 3 }, __B_bitset: bitset, __B_known: known }, 'x'],
    ['bit computed and zero', { __B_index: { x: 1 }, __B_bitset: bitset, __B_known: known }, 'x'],
    ['bit computed and one', { __B_index: { x: 0 }, __B_bitset: bitset, __B_known: known }, 'x']
  ];
  let cornerMism = 0;
  const cornerOut = [];
  for (const [name, mwLike, inscode] of corners) {
    const a = fnOrig({ inscode: inscode }, mwLike);
    const b = fnBundle({ inscode: inscode }, mwLike);
    if (a !== b) cornerMism++;
    cornerOut.push(name + '=' + a);
  }
  check('fail-open corners identical', cornerMism === 0, cornerOut.join(', '));
  check('every fail-open corner returns true (nothing hidden)',
    corners.every(function (c) { return fnBundle({ inscode: c[2] }, c[1]) === true; }),
    cornerOut.join(', '));
}

// ---------- summary ----------
console.log('\n=== SUMMARY ===');
console.log('  pass=' + pass + ' fail=' + fail);
if (fail > 0) { console.log('  FAILED: ' + failures.join('; ')); process.exit(1); }
console.log('  OK — the generated browser bundle is behaviourally identical to the sources.');
